<?php
return function(PDO $db): void {
    $db->exec("ALTER TABLE users ADD COLUMN IF NOT EXISTS phone VARCHAR(40) NULL, ADD COLUMN IF NOT EXISTS status ENUM('active','disabled') DEFAULT 'active'");
    $db->exec("ALTER TABLE courses ADD COLUMN IF NOT EXISTS mode ENUM('Présentiel','En ligne','Mixte') DEFAULT 'Présentiel', ADD COLUMN IF NOT EXISTS duration_label VARCHAR(80) DEFAULT '1 jour', ADD COLUMN IF NOT EXISTS price DECIMAL(12,2) DEFAULT 0, ADD COLUMN IF NOT EXISTS tone VARCHAR(30) DEFAULT 'navy'");
    if((int)$db->query('SELECT COUNT(*) FROM courses')->fetchColumn()===0){$s=$db->prepare("INSERT INTO courses(title,slug,description,category,status,mode,duration_label,price,tone) VALUES(?,?,?,?,?,?,?,?,?)");foreach([['Le Métier de Sous-Gérant en Station-Service','sous-gerant-station-service','Formation opérationnelle complète.','Aval pétrolier','published','Présentiel','4 jours',75000,'navy'],['Le Dépotage du Carburant en Station-Service','depotage-carburant','Maîtriser la sécurité du dépotage.','Aval pétrolier','published','En ligne','8 heures',45000,'gold'],['Graissage et Vente des Lubrifiants','graissage-lubrifiants','Techniques de graissage et vente.','Aval pétrolier','published','Mixte','3 jours',50000,'green']] as $r)$s->execute($r);}
    if((int)$db->query('SELECT COUNT(*) FROM products')->fetchColumn()===0){$s=$db->prepare("INSERT INTO products(name,slug,reference,description,price,stock_status,stock_quantity,lead_time,status) VALUES(?,?,?,?,?,?,?,?,?)");foreach([['Pompe à carburant','pompe-carburant','IF-POMPE','Pompe professionnelle.',null,'in_stock',2,null,'published'],['Pistolet de distribution','pistolet-distribution','IF-PISTOLET','Pistolet professionnel.',85000,'in_stock',12,null,'published'],['Sabre de jauge','sabre-de-jauge','IF-SJ-1000','Instrument professionnel de mesure.',45000,'on_order',0,'5 à 7 jours','published'],['Pâte Kolor Kut','pate-kolor-kut','IF-KK','Pâte de détection.',18000,'in_stock',25,null,'published']] as $r)$s->execute($r);}
};
